        found = collect_findings(_styled_scene(opacity=60))
        self.assertEqual(
            [f for f in found if f["check"] == "contrast_object"], [],
            "the non-text floor spoke about a 4.38:1 object, which "
            "clears 3:1 — the two contrast floors have collapsed onto "
            "one constant")
